//! Embedded style DEFINITIONS: one record per design style that the product
//! records of [`crate::design_data`] cite as `external:<ref>` (for example
//! `external:minimalism-and-swiss-style`). Without these records an agent gets
//! a style name it cannot read.
//!
//! The file (`design-styles-uiuxpm.json`, generated by
//! `scripts/import-ui-ux-pro-max.py`) is third-party data and is treated like
//! the product tables: every string has a length cap and no control
//! characters, a REQUIRED `source` carries licence and commit, and ONE bad
//! record rejects the whole file (an empty table is safe, a half-trusted one
//! is not). The file is loaded independently of the product tables, see
//! [`crate::design_data::load_all_tables`]. Search and the JSON served to the
//! model live in [`crate::design_styles_search`].

use serde_json::Value;

use crate::design_data::{
    is_hex_color, is_slug, parse_source, problem, DesignDataError, DesignSource, FieldProblem,
    Reader, EXTERNAL_STYLE_PREFIX, MAX_DATA_BYTES, MAX_KEYWORDS, MAX_KEYWORD_CHARS, MAX_NAME_CHARS,
    MAX_RECORDS, MAX_STYLE_CHARS,
};

/// Every style id starts with this; the rest is the record's `ref`.
pub const STYLE_ID_PREFIX: &str = "uiuxpm-style-";
/// A product style entry is `external:<ref>` within [`MAX_STYLE_CHARS`].
pub const MAX_REF_CHARS: usize = MAX_STYLE_CHARS - EXTERNAL_STYLE_PREFIX.len();
pub const MAX_STYLE_ID_CHARS: usize = STYLE_ID_PREFIX.len() + MAX_REF_CHARS;
/// Longest prose field (best for, effects, ...).
pub const MAX_PROSE_CHARS: usize = 400;
/// Most colours in one palette hint.
pub const MAX_COLORS: usize = 8;

/// One design style: what it is for, what it is not for, and how it behaves.
/// Optional fields are `None` / empty when the upstream cell had nothing usable.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StyleRecord {
    /// `uiuxpm-style-<ref>`.
    pub id: String,
    /// The name product records cite after `external:`; unique in the table.
    pub reference: String,
    pub name: String,
    /// Search-only words (aliases first).
    pub keywords: Vec<String>,
    pub category: Option<String>,
    pub best_for: Option<String>,
    pub do_not_use_for: Option<String>,
    pub effects: Option<String>,
    pub era: Option<String>,
    pub complexity: Option<String>,
    pub accessibility: Option<String>,
    pub light_dark_mode: Option<String>,
    pub status: Option<String>,
    /// `#rrggbb` hints found in the upstream colour cells.
    pub primary_colors: Vec<String>,
    pub secondary_colors: Vec<String>,
    pub source: DesignSource,
}

impl Reader<'_> {
    /// A text field that may be absent; present means non-empty and capped.
    fn optional_text(&self, field: &str, max: usize) -> Result<Option<String>, DesignDataError> {
        if self.object.contains_key(field) {
            self.text(field, max).map(Some)
        } else {
            Ok(None)
        }
    }

    /// A list of `#rrggbb` colours that may be absent.
    fn optional_colors(&self, field: &str) -> Result<Vec<String>, DesignDataError> {
        if !self.object.contains_key(field) {
            return Ok(Vec::new());
        }
        let colors = self.texts(field, MAX_COLORS, 7, true)?;
        if colors.iter().any(|color| !is_hex_color(color)) {
            return Err(self.fail(field, FieldProblem::BadFormat("#rrggbb colours")));
        }
        Ok(colors
            .iter()
            .map(|color| color.to_ascii_lowercase())
            .collect())
    }
}

/// Parse and validate a styles JSON document. Pure, like
/// [`crate::design_data::parse_design_data`].
pub fn parse_style_data(raw: &str) -> Result<Vec<StyleRecord>, DesignDataError> {
    if raw.len() > MAX_DATA_BYTES {
        return Err(DesignDataError::TooLarge { bytes: raw.len() });
    }
    let root: Value = serde_json::from_str(raw).map_err(DesignDataError::Json)?;
    let Value::Array(items) = root else {
        return Err(DesignDataError::NotAnArray);
    };
    if items.len() > MAX_RECORDS {
        return Err(DesignDataError::TooManyRecords { count: items.len() });
    }
    let mut records: Vec<StyleRecord> = Vec::with_capacity(items.len());
    for (index, item) in items.iter().enumerate() {
        let record = parse_style_record(index, item)?;
        if records
            .iter()
            .any(|earlier| earlier.id == record.id || earlier.reference == record.reference)
        {
            return Err(problem(&record.id, "id", FieldProblem::DuplicateId));
        }
        records.push(record);
    }
    Ok(records)
}

fn parse_style_record(index: usize, item: &Value) -> Result<StyleRecord, DesignDataError> {
    let placeholder = format!("#{index}");
    let Value::Object(object) = item else {
        return Err(problem(&placeholder, "(record)", FieldProblem::WrongType));
    };
    let mut reader = Reader {
        label: placeholder,
        object,
    };
    let id = reader.text("id", MAX_STYLE_ID_CHARS)?;
    if !is_slug(&id) || !id.starts_with(STYLE_ID_PREFIX) {
        return Err(reader.fail(
            "id",
            FieldProblem::BadFormat("a slug prefixed with uiuxpm-style-"),
        ));
    }
    reader.label = id.clone();
    let reference = reader.text("ref", MAX_REF_CHARS)?;
    if !is_slug(&reference) || id != format!("{STYLE_ID_PREFIX}{reference}") {
        return Err(reader.fail(
            "ref",
            FieldProblem::BadFormat("a slug that completes the id"),
        ));
    }
    let keywords = reader.texts("keywords", MAX_KEYWORDS, MAX_KEYWORD_CHARS, true)?;
    for keyword in &keywords {
        if keyword.contains('\n')
            || keyword.trim() != keyword
            || keyword.chars().any(|c| c.is_uppercase())
        {
            return Err(reader.fail(
                "keywords",
                FieldProblem::BadFormat("trimmed, single-line and lower-case"),
            ));
        }
    }
    let source = parse_source(&reader.object("source")?)?;
    Ok(StyleRecord {
        name: reader.text("name", MAX_NAME_CHARS)?,
        category: reader.optional_text("category", 40)?,
        best_for: reader.optional_text("bestFor", MAX_PROSE_CHARS)?,
        do_not_use_for: reader.optional_text("doNotUseFor", MAX_PROSE_CHARS)?,
        effects: reader.optional_text("effects", MAX_PROSE_CHARS)?,
        era: reader.optional_text("era", 60)?,
        complexity: reader.optional_text("complexity", 40)?,
        accessibility: reader.optional_text("accessibility", MAX_PROSE_CHARS)?,
        light_dark_mode: reader.optional_text("lightDarkMode", 120)?,
        status: reader.optional_text("status", 40)?,
        primary_colors: reader.optional_colors("primaryColors")?,
        secondary_colors: reader.optional_colors("secondaryColors")?,
        keywords,
        source,
        reference,
        id,
    })
}

/// Every validated style record, parsed once with the product tables (a bad
/// styles file is empty here, never a panic).
pub fn style_records() -> &'static [StyleRecord] {
    &crate::design_data::design_tables().styles
}

/// `Minimalism & Swiss Style` -> `minimalism swiss style`: lower-case words,
/// every other character a separator.
pub(crate) fn words_key(text: &str) -> String {
    let lower = text.to_lowercase();
    let spaced: String = lower
        .chars()
        .map(|c| if c.is_alphanumeric() { c } else { ' ' })
        .collect();
    spaced.split_whitespace().collect::<Vec<_>>().join(" ")
}

/// The query without an `external:` prefix, trimmed and lower-cased.
pub(crate) fn strip_external(query: &str) -> String {
    let lower = query.trim().to_lowercase();
    lower
        .strip_prefix(EXTERNAL_STYLE_PREFIX)
        .unwrap_or(&lower)
        .trim()
        .to_string()
}

/// Does `query` (already through [`strip_external`]) name exactly this style:
/// its ref, its id or its display name, ignoring case and punctuation?
pub(crate) fn names_style(record: &StyleRecord, query: &str) -> bool {
    if query.is_empty() {
        return false;
    }
    if query == record.reference || query == record.id {
        return true;
    }
    let key = words_key(query);
    !key.is_empty() && (key == words_key(&record.name) || key == words_key(&record.reference))
}

/// The style a product record cites: `external:minimalism-and-swiss-style`,
/// the bare ref, the id or the display name all find it.
pub fn style_by_ref(name: &str) -> Option<&'static StyleRecord> {
    find_style(style_records(), name)
}

pub(crate) fn find_style<'a>(records: &'a [StyleRecord], name: &str) -> Option<&'a StyleRecord> {
    let query = strip_external(name);
    records.iter().find(|record| names_style(record, &query))
}

